  console.warn('⚠️  ADMIN_PASSWORD_HASH não definido! Gere com: node -e "console.log(require(\'bcrypt\').hashSync(\'sua_senha\', 12))"');
}
if (!SESSION_SECRET || SESSION_SECRET.length < 32) {
  console.warn('⚠️  SESSION_SECRET fraco ou ausente! Gere com: openssl rand -hex 32');
}

app.use(session({
  secret: [REDACTED] || 'dev-only-change-in-production',
  resave: false,
  saveUninitialized: false,
  cookie: [REDACTED]
    secure: IS_PROD,
    httpOnly: true,
    sameSite: 'lax',
    maxAge: 1000 * 60 * 60 * 24 // 24h
  }
}));

const checkAuth = (req, res, next) => {
  if (req.session.loggedin) {
    next();
  } else {
    res.redirect('/login.html');
  }
};

// --- Rate Limiting ---
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Muitas requisições, tente novamente mais tarde.' }
});
app.use(globalLimiter);

const leadLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 min
  max: 5,
