  tipoEvento: z.enum(['Casamento', 'Formatura', 'Aniversário', 'Inauguração', 'Corporativo', 'Outro']),
  dataEvento: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Data inválida (YYYY-MM-DD)'),
  convidados: z.coerce.number().int().min(1, 'Mínimo 1 convidado').max(2000),
  mensagem: z.string().max(2000).optional()
