  try {
    const data = await fs.readFile(dbPath, 'utf8');
    db = JSON.parse(data);
    console.log('✅ db.json carregado');
  } catch (err) {
    console.error('❌ Erro ao ler db.json:', err.message);
    db = { leads: [] };
  }
}

